public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Determine the maximum string length to set upper bound for L
    int maxLen = 0;
    for (String s : strings) {
        if (s == null) continue;
        maxLen = Math.max(maxLen, s.length());
    }
    // Try lengths from maxLen down to 1
    for (int L = maxLen; L >= 1; L--) {
        java.util.Set<String> candidates = null;
        boolean failed = false;
        for (String s : strings) {
            if (s == null || s.length() < L) {
                failed = true;
                break;
            }
            java.util.Set<String> current = new java.util.HashSet<>();
            for (int i = 0; i <= s.length() - L; i++) {
                String sub = s.substring(i, i + L);
                current.add(sub);
                // Add the reversed variant as well
                current.add(new java.lang.StringBuilder(sub).reverse().toString());
            }
            if (candidates == null) {
                candidates = current;
            } else {
                candidates.retainAll(current);
                if (candidates.isEmpty()) {
                    failed = true;
                    break;
                }
            }
        }
        if (!failed && candidates != null && !candidates.isEmpty()) {
            return L;
        }
    }
    return 0; // No common substring found
}

