public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Build adjacency list from given paths
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    for (int i = 0; i < paths.length; i++) {
        int[] edge = paths[i];
        if (edge.length < 4) continue; // Invalid edge specification, skip
        String a = edge[0] + "," + edge[1];
        String b = edge[2] + "," + edge[3];
        graph.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        graph.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    }

    // Convert start and end coordinates to string keys
    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];

    // If start equals end, it's trivially reachable
    if (startKey.equals(endKey)) return "can be travelled";

    // Breadth‑first search to find a path
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = graph.get(current);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (nb.equals(endKey)) return "can be travelled";
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    int len1 = word1.length();
    int len2 = word2.length();
    int denominator = len1 + len2;

    // Build sets of unique characters for each word
    java.util.Set<Character> set1 = new java.util.HashSet<>();
    java.util.Set<Character> set2 = new java.util.HashSet<>();
    for (char c : word1.toCharArray()) {
        set1.add(c);
    }
    for (char c : word2.toCharArray()) {
        set2.add(c);
    }

    // Count distinct common letters
    int commonCount = 0;
    for (char c : set1) {
        if (set2.contains(c)) {
            commonCount++;
        }
    }

    int numerator = 2 * commonCount; // each common letter counted in both words

    if (numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    // Reduce fraction to lowest terms
    int gcd = java.lang.Math.abs(gcd(numerator, denominator));
    int redNum = numerator / gcd;
    int redDen = denominator / gcd;

    String value;
    if (redDen == 1) {
        value = Integer.toString(redNum);
    } else {
        value = redNum + "/" + redDen;
    }

    return "appx(" + word1 + ", " + word2 + ") = " + value;
}

