    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    int[] res = new int[1];
    class Helper {
        boolean dfs(int node, int parent) {
            boolean containsApple = hasApple[node];
            for (int nei : graph[node]) {
                if (nei == parent) continue;
                if (dfs(nei, node)) {
