    return res[0];
}

public String sortString(String s) {
    TreeMap<Character, Integer> freq = new TreeMap<>();
    for (char c : s.toCharArray()) {
        freq.put(c, freq.getOrDefault(c, 0) + 1);
    }
    StringBuilder result = new StringBuilder();
    while (!freq.isEmpty()) {
        // Ascending pass
        for (Character c : new ArrayList<>(freq.keySet())) {
            result.append(c);
            int count = freq.get(c) - 1;
            if (count == 0) {
                freq.remove(c);
            } else {
                freq.put(c, count);
            }
        }
        if (freq.isEmpty()) break;
        // Descending pass
        for (Character c : new ArrayList<>(freq.descendingKeySet())) {
            result.append(c);
            int count = freq.get(c) - 1;
            if (count == 0) {
                freq.remove(c);
            } else {
                freq.put(c, count);
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;

    int l1Size = n / 2;
    int l2Size = n - l1Size;

    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] first = new java.util.HashSet[n + 1];
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] second = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        first[i] = new java.util.HashSet<>();
        second[i] = new java.util.HashSet<>();
    }

    // Enumerate subsets of the first half
    int limit1 = 1 << l1Size;
    for (int mask = 0; mask < limit1; mask++) {
        int sum = 0;
        int cnt = 0;
        for (int i = 0; i < l1Size; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[i];
                cnt++;
            }
        }
        first[cnt].add(sum);
    }

    // Enumerate subsets of the second half
    int limit2 = 1 << l2Size;
    int offset = l1Size;
    for (int mask = 0; mask < limit2; mask++) {
        int sum = 0;
        int cnt = 0;
        for (int i = 0; i < l2Size; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[offset + i];
                cnt++;
            }
        }
        second[cnt].add(sum);
    }

    // Check possible subset sizes
    for (int k = 1; k < n; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        int minFirst = Math.max(0, k - l2Size);
        int maxFirst = Math.min(k, l1Size);
        for (int i = minFirst; i <= maxFirst; i++) {
            int j = k - i;
            if (j < 0 || j > l2Size) continue;
            for (int sumFirst : first[i]) {
                if (second[j].contains(target - sumFirst)) {
                    return true;
                }
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    int prevPrev = 0; // minimum cost to reach step 0
    int prev = 0;     // minimum cost to reach step 1
    for (int i = 2; i <= n; i++) {
        int cur = Math.min(prev + cost[i - 1], prevPrev + cost[i - 2]);
        prevPrev = prev;
        prev = cur;
    }
    return prev; // minimum cost to reach the top (step n)
}

