public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k > n) return false;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int curr = 0;
    // Initialize first window
    for (int i = 0; i < k; i++) {
        curr = (curr << 1) | (s.charAt(i) - '0');
    }
    seen[curr] = true;
    int count = 1;
    for (int i = k; i < n; i++) {
        curr = ((curr << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[curr]) {
            seen[curr] = true;
            count++;
            if (count == total) return true; // all codes found early
        }
    }
    return count == total;
}

