public int minInsertions(String s) {
    int insertions = 0;
    int balance = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                insertions++;   // need a '(' before this ')'
                balance++;       // account for the inserted '('
            }
            balance--;           // consume the ')'
        }
    }
    insertions += balance;      // add ')' for remaining unmatched '('
    return insertions;
}

