    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int max = 0;
    int totalMasks = 1 << Math.max(0, n - 1);
    for (int mask = 0; mask < totalMasks; mask++) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        int last = 0;
        int count = 0;
        boolean bad = false;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) { // split after position i
                String part = s.substring(last, i + 1);
                if (!seen.add(part)) { bad = true; break; }
                count++;
                last = i + 1;
            }
        }
        if (bad) continue;
        String part = s.substring(last);
        if (!seen.add(part)) continue;
        count++;
        if (count > max) max = count;
    }
    return max;
}

public int minOperations(String[] logs) {  
