        return 0;  
    }  
    int depth = 0;  
    for (String log : logs) {  
        if ("../".equals(log)) {  
            if (depth > 0) {  
                depth--;  
            }  
        } else if ("./".equals(log)) {  
            // stay in the same folder, do nothing  
        } else {  
            // entering a new folder  
            depth++;  
        }  
    }  
    return depth;  
}

public String getSmallestString(int n, int k) {
    int remaining = k - n; // extra value needed beyond all 'a'
    char[] chars = new char[n];
    // initialize with 'a'
    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }
    // fill from the end to keep lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(remaining, 25); // 'z' - 'a' = 25
        chars[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(chars);
}

