}

public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    java.util.Queue<Long> queue = new java.util.LinkedList<>();

    // Start BFS with numbers 1 to 9
    for (int i = 1; i <= 9; i++) {
        queue.offer((long)i);
    }

    while (!queue.isEmpty()) {
        long current = queue.poll();
        if (current > high) {
            continue; // no need to expand further
        }

        if (current >= low) {
            result.add((int)current);
        }

        int lastDigit = (int)(current % 10);

        // Extend the current number by appending digits that differ by 1
        if (lastDigit > 0) {
            long next = current * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = current * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    // Include 0 if it is within the range
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }

    // Sort the result in ascending order
    java.util.Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    int count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long lower = n % factor;                     // digits on the right
        int cur = (int) ((n / factor) % 10);          // current digit
        long higher = n / (factor * 10);              // digits on the left

        count += (int) (higher * factor);

        if (cur == 1) {
            count += (int) (lower + 1);
        } else if (cur > 1) {
            count += (int) factor;
        }
    }
    return count;
}

