    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = numStr.length() - 1; i >= 0; i--) {
        sb.append(numStr.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }
    if (negative) sb.append('-');
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    boolean[][] ok = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j) {
                int sum = A[i] + A[j];
                int r = (int) Math.sqrt(sum);
                ok[i][j] = (r * r == sum);
            } else {
                ok[i][j] = false;
            }
        }
    }
    int maxMask = 1 << n;
    int[][] memo = new int[maxMask][n];
    for (int i = 0; i < maxMask; i++) {
        for (int j = 0; j < n; j++) {
            memo[i][j] = -1;
        }
    }
    long total = 0;
    for (int start = 0; start < n; start++) {
        total += dfs(1 << start, start, memo, ok);
    }
    return (int) total;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    // Stack to hold indices of bars, maximum size n+1 to handle dummy at end
    int[] stack = new int[n + 1];
    int top = -1;
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        // Use 0 as sentinel height after the last bar
        int curHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && curHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    if (m == 0) return new int[0];
    int n = mat[0].length;
    int[] res = new int[m * n];
    int idx = 0;
    for (int d = 0; d <= m + n - 2; d++) {
        int rStart = Math.max(0, d - n + 1);
        int rEnd = Math.min(m - 1, d);
        if (d % 2 == 0) {
            for (int r = rEnd; r >= rStart; r--) {
                int c = d - r;
                res[idx++] = mat[r][c];
            }
        } else {
            for (int r = rStart; r <= rEnd; r++) {
                int c = d - r;
                res[idx++] = mat[r][c];
            }
        }
    }
    return res;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = digits.length - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    int left = i + 1;
    int right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    String resultStr = new String(digits);
    long resultLong;
    try {
        resultLong = Long.parseLong(resultStr);
    } catch (NumberFormatException e) {
        return -1;
    }
    if (resultLong > Integer.MAX_VALUE) {
        return -1;
    }
    return (int) resultLong;
}

